<script setup lang="ts">import {onMounted,ref} from 'vue';import {api,get} from '../../api/http';import {useRoute,useRouter} from 'vue-router';const route=useRoute(),router=useRouter(),id=route.params.id as string|undefined;const tags=ref<any[]>([]);const f=ref<any>({title:'',slug:'',summary:'',content:'# 新文章',coverUrl:'',status:'DRAFT',categoryId:null,tagIds:[]});onMounted(async()=>{tags.value=await get('/tags');if(id)f.value=await get('/admin/articles/'+id)});async function save(){try{if(id)await api.put('/admin/articles/'+id,f.value);else await api.post('/admin/articles',f.value);router.push('/admin/articles')}catch{alert('保存失败：请检查必填字段或 slug 是否重复')}}async function publish(){if(!id)return;await api.post('/admin/articles/'+id+'/publish');router.push('/admin/articles')}</script><template><h1>{{id?'编辑文章':'新建文章'}}</h1><form @submit.prevent="save" class="editor"><input v-model="f.title" placeholder="标题" required><input v-model="f.slug" placeholder="slug" required><textarea v-model="f.summary" placeholder="摘要"></textarea><select v-model="f.status"><option>DRAFT</option><option>PUBLISHED</option><option>ARCHIVED</option></select><label>标签 <select v-model="f.tagIds" multiple><option v-for="t in tags" :key="t.id" :value="t.id">{{t.name}}</option></select></label><textarea v-model="f.content" class="content" placeholder="Markdown 正文" required></textarea><button>保存</button><button v-if="id" type="button" @click="publish">发布</button></form></template>
